1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.AfterMapping;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.mapstruct.MappingTarget;
8	import org.springframework.data.domain.Page;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.model.OwnerIdentity;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	
15	import java.nio.charset.StandardCharsets;
16	import java.util.Collection;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.UUID;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    Owner toOwner(OwnerDto ownerDto);
30	
31	    @Mapping(target = "id", ignore = true)
32	    @Mapping(target = "pets", ignore = true)
33	    Owner toOwner(OwnerFieldsDto ownerDto);
34	
35	    /**
36	     * Derives the household identifier for the response: a stable value shared by owners with the
37	     * same last name and address (case- and whitespace-insensitive), so members of one household
38	     * always report the same id. Non-persistent, so it never affects storage or the request payload.
39	     */
40	    @AfterMapping
41	    default void deriveHouseholdId(Owner owner, @MappingTarget OwnerDto ownerDto) {
42	        String lastName = owner.getLastName();
43	        String address = owner.getAddress();
44	        if (lastName == null || address == null) {
45	            return;
46	        }
47	        String key = (lastName.strip().replaceAll("\\s+", " ") + '\n'
48	            + address.strip().replaceAll("\\s+", " ")).toLowerCase();
49	        ownerDto.setHouseholdId(UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString());
50	    }
51	
52	    /**
53	     * Derives 'identityKey' for the response: the single duplicate-detection key from
54	     * {@link OwnerIdentity#key(Owner)}. Non-persistent, so it never affects storage or the request payload.
55	     */
56	    @AfterMapping
57	    default void deriveIdentityKey(Owner owner, @MappingTarget OwnerDto ownerDto) {
58	        ownerDto.setIdentityKey(OwnerIdentity.key(owner));
59	    }
60	
61	    /** Fixed city-to-region table used to derive an owner's locality. */
62	    Map<String, String> CITY_REGION = Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
63	
64	    /**
65	     * Derives 'locality' for the response: the canonical region for the owner's city from the fixed
66	     * {@link #CITY_REGION} table, or 'UNKNOWN' when the city is not listed. Non-persistent, so it
67	     * never affects storage or the request payload.
68	     */
69	    @AfterMapping
70	    default void deriveLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
71	        ownerDto.setLocality(CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN"));
72	    }
73	
74	    /**
75	     * Derives 'contactPreference' for the response: 'EMAIL' when the owner has an email address,
76	     * otherwise 'PHONE'. Non-persistent, so it never affects storage or the request payload.
77	     */
78	    @AfterMapping
79	    default void deriveContactPreference(Owner owner, @MappingTarget OwnerDto ownerDto) {
80	        String email = owner.getEmail();
81	        ownerDto.setContactPreference(email == null || email.isBlank() ? "PHONE" : "EMAIL");
82	    }
83	
84	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
85	
86	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
87	
88	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
89	        OwnerPageDto ownerPageDto = new OwnerPageDto();
90	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
91	        ownerPageDto.setPage(ownerPage.getNumber());
92	        ownerPageDto.setSize(ownerPage.getSize());
93	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
94	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
95	        return ownerPageDto;
96	    }
97	}
